class Solution:
    def minMoves(self, nums: List[int], k: int) -> int:
        b = []
        for i, v in enumerate(nums):
            if v == 1:
                b.append(i - len(b))
        best = float('inf')
        for i in range(len(b) - k + 1):
            m = b[i + k // 2]
            best = min(best, sum(abs(x - m) for x in b[i:i + k]))
        return int(best)

