class Solution {
public:
    int minMoves(vector<int>& nums, int k) {
        vector<long long> b;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] == 1) b.push_back((long long)i - (int)b.size());
        long long best = LLONG_MAX;
        int c = b.size();
        for (int i = 0; i + k <= c; i++) {
            long long m = b[i + k / 2], cost = 0;
            for (int j = i; j < i + k; j++) cost += llabs(b[j] - m);
            best = min(best, cost);
        }
        return (int)best;
    }
};

