    const pre = new Array(c + 1).fill(0);
    for (let i = 0; i < c; i++) pre[i + 1] = pre[i] + b[i];
    let best = Infinity;
    for (let i = 0; i + k <= c; i++) {
        const mid = i + (k >> 1);
        const m = b[mid];
        const left = m * (mid - i) - (pre[mid] - pre[i]);
        const right = (pre[i + k] - pre[mid + 1]) - m * (i + k - 1 - mid);
        best = Math.min(best, left + right);
    }
    return best;
};
